import java.util.List;
import java.util.Collections;

// Simplified mock types for example compilation. 
// In a real JDT environment, $cu would be org.eclipse.jdt.core.dom.CompilationUnit.
class MySimpleName { // Analogous to org.eclipse.jdt.core.dom.SimpleName
    String id;
    MySimpleName(String id) { this.id = id; }
    public String getIdentifier() { return id; }
}

class MyTypeDeclaration { // Analogous to org.eclipse.jdt.core.dom.AbstractTypeDeclaration
    MySimpleName name;
    MyTypeDeclaration(MySimpleName name) { this.name = name; }
    public MySimpleName getName() { return name; }
}

class MyCompilationUnit { // Analogous to org.eclipse.jdt.core.dom.CompilationUnit
    List<MyTypeDeclaration> types;
    MyCompilationUnit(List<MyTypeDeclaration> types) { this.types = types; }
    public List<MyTypeDeclaration> types() { return types; }
    public int hashCode() { return 12345; } // Predictable for example
}

public class Example {
    // The DSL rule's guard 'instanceof($cu, "org.eclipse.jdt.core.dom.CompilationUnit")'
    // would match a real JDT CompilationUnit, not 'MyCompilationUnit'.
    // This example demonstrates the textual transformation assuming the guard passes.
    public String getAstDebugInfo(MyCompilationUnit cu) {
        List<MyTypeDeclaration> types = cu.types();
        if (types != null && !types.isEmpty()) {
            return types.get(0).getName().getIdentifier();
        } else {
            return "AST without any type";
        }
    }
}

